import { Bot, Boxes, Compass, Database, GitBranch, Info, Plus, Settings } from 'lucide-react';
import { NavLink, useLocation } from 'react-router';

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from '@/components/ui/context-menu';
import {
  Sidebar,
  SidebarGroup,
  SidebarGroupAction,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar';

import type { WorkspaceRecord } from '../types/dto';

export interface AppSidebarProps {
  /** workspace 清单 */
  workspaces: WorkspaceRecord[];
  /** 当前选中根（启动恢复/移除顺延取默认序第一名，切换为本地 state） */
  currentRoot: string;
  /** 点击清单项 */
  onOpen: (root: string) => void;
  /** 「＋」添加：文件夹选择器 → add_workspace 入库 */
  onAdd: () => void;
  /** 右键「移除」：remove_workspace，无确认弹窗、不触盘上目录 */
  onRemove: (root: string) => void;
}

/** root 去掉最后一段的完整前缀（最后一个 / 或 \ 之前）；无分隔符返回空串（design D3） */
function parentDir(root: string): string {
  const index = Math.max(root.lastIndexOf('/'), root.lastIndexOf('\\'));
  return index === -1 ? '' : root.slice(0, index);
}

function WorkspaceItem({
  record,
  currentRoot,
  onOpen,
  onRemove,
}: {
  record: WorkspaceRecord;
  currentRoot: string;
  onOpen: (root: string) => void;
  onRemove: (root: string) => void;
}): React.JSX.Element {
  const parent = parentDir(record.root);
  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>
        <SidebarMenuItem>
          <SidebarMenuButton
            data-root={record.root}
            data-testid="workspace-item"
            isActive={record.root === currentRoot}
            size="lg"
            tooltip={record.root}
            onClick={() => onOpen(record.root)}
          >
            {/* leading-tight 收紧行高，主文本 + 父目录两行在 lg（h-12）内完整呈现 */}
            <span className="flex min-w-0 flex-col leading-tight">
              <span className="truncate">{record.name}</span>
              {parent !== '' && (
                <span
                  className="block truncate text-xs font-normal text-muted-foreground"
                  data-testid="workspace-sub"
                >
                  {parent}
                </span>
              )}
            </span>
          </SidebarMenuButton>
        </SidebarMenuItem>
      </ContextMenuTrigger>
      <ContextMenuContent>
        <ContextMenuItem onClick={() => onRemove(record.root)}>移除</ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

/** 页面导航单项：SidebarMenuItem + NavLink 路由入口（active 由当前 URL 派生） */
function PageNavItem({
  to,
  testId,
  icon,
  label,
  active,
}: {
  to: string;
  testId: string;
  icon: React.JSX.Element;
  label: string;
  active: boolean;
}): React.JSX.Element {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton asChild isActive={active} tooltip={label}>
        <NavLink data-testid={testId} to={to}>
          {icon}
          <span>{label}</span>
        </NavLink>
      </SidebarMenuButton>
    </SidebarMenuItem>
  );
}

/** 页面导航组：[基础信息] [变更] [探索] [配置]，NavLink 路由入口（active 由当前 URL 派生） */
function PageNavGroup(): React.JSX.Element {
  const { pathname } = useLocation();
  return (
    <SidebarGroup>
      <SidebarGroupLabel>页面</SidebarGroupLabel>
      <SidebarGroupContent>
        <SidebarMenu>
          {/* 基础信息项：/info（workspace 域内容页首位） */}
          <PageNavItem
            active={pathname === '/info'}
            icon={<Info />}
            label="基础信息"
            testId="nav-info"
            to="/info"
          />
          {/* 变更项：/changes 与 /changes/:name（详情）均 active */}
          <PageNavItem
            active={pathname === '/changes' || pathname.startsWith('/changes/')}
            icon={<GitBranch />}
            label="变更"
            testId="nav-changes"
            to="/changes"
          />
          {/* 探索项：/explores 与 /explores/:name（详情）均 active */}
          <PageNavItem
            active={pathname === '/explores' || pathname.startsWith('/explores/')}
            icon={<Compass />}
            label="探索"
            testId="nav-explores"
            to="/explores"
          />
          {/* 配置项：/config（workspace 域内容页组内末位） */}
          <PageNavItem
            active={pathname === '/config'}
            icon={<Settings />}
            label="配置"
            testId="nav-config"
            to="/config"
          />
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

/** 系统工具导航组：[Agent 管理]（调试的配置前置）[Agent 调试] [数据库]，系统级工具入口 */
function SystemToolsGroup(): React.JSX.Element {
  const { pathname } = useLocation();
  return (
    <SidebarGroup>
      <SidebarGroupLabel>系统工具</SidebarGroupLabel>
      <SidebarGroupContent>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton asChild isActive={pathname === '/agents'} tooltip="Agent 管理">
              <NavLink data-testid="nav-agents" to="/agents">
                <Boxes />
                <span>Agent 管理</span>
              </NavLink>
            </SidebarMenuButton>
          </SidebarMenuItem>
          <SidebarMenuItem>
            <SidebarMenuButton asChild isActive={pathname === '/agent'} tooltip="Agent 调试">
              <NavLink data-testid="nav-agent" to="/agent">
                <Bot />
                <span>Agent 调试</span>
              </NavLink>
            </SidebarMenuButton>
          </SidebarMenuItem>
          <SidebarMenuItem>
            <SidebarMenuButton asChild isActive={pathname === '/db'} tooltip="数据库">
              <NavLink data-testid="nav-db" to="/db">
                <Database />
                <span>数据库</span>
              </NavLink>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

/**
 * 侧栏（仅壳态挂载）：上方「页面」导航组（[基础信息] [变更] [探索] [配置]），中部「工作区」清单组
 * （语义不变），下方「系统工具」组（[Agent 管理] [Agent 调试] [数据库]，
 * 首次出现非 workspace 入口语义）。列表项点击切换（副文本父目录区分同名、
 * Tooltip 完整 root），「＋」添加、右键 ContextMenu 移除。
 */
export function AppSidebar({
  workspaces,
  currentRoot,
  onOpen,
  onAdd,
  onRemove,
}: AppSidebarProps): React.JSX.Element {
  return (
    <Sidebar collapsible="icon">
      <PageNavGroup />
      <SidebarGroup>
        <SidebarGroupLabel>工作区</SidebarGroupLabel>
        <SidebarGroupAction aria-label="添加 workspace" onClick={onAdd}>
          <Plus />
        </SidebarGroupAction>
        <SidebarGroupContent>
          <SidebarMenu>
            {workspaces.map((record) => (
              <WorkspaceItem
                currentRoot={currentRoot}
                key={record.root}
                onOpen={onOpen}
                onRemove={onRemove}
                record={record}
              />
            ))}
          </SidebarMenu>
        </SidebarGroupContent>
      </SidebarGroup>
      <SystemToolsGroup />
    </Sidebar>
  );
}

